import * as $ from 'svelte/internal/server';

export default function Basic_runes($$renderer) {
	let count = 0;
	let items = ["a", "b", "c"];

	$$renderer.push(`<div class="root">`);

	if (count > 0) {
		$$renderer.push('<!--[0-->');
		$$renderer.push(`<p>0</p>`);
	} else {
		$$renderer.push('<!--[-1-->');
		$$renderer.push(`<p>zero</p>`);
	}

	$$renderer.push(`<!--]--> <ul><!--[-->`);

	const each_array = $.ensure_array_like(items);

	for (let $$index = 0, $$length = each_array.length; $$index < $$length; $$index++) {
		let item = each_array[$$index];

		$$renderer.push(`<li>${$.escape(item)}</li>`);
